/* What a community's admins and moderators may do, run after part 81. One new column on `communities`, `role_permissions` (a JSON object, empty by default), where the owner keeps what they changed from the defaults: for `admin` and `moderator`, a group of actions turned on or off (removing and pinning posts, muting and banning members, reports, the audit log, announcements, invites and roles, spaces, Learn, the calendar, settings, analytics). Money, deleting the community and handing it over always stay with the owner, whatever is stored. An empty object means the roles as they were: admins do everything but money and deleting, moderators keep posts, comments and members in order. Server only: it is not one of the columns members and visitors can read, and only the service role writes it, after the owner check in the app. No existing rows change. Until it runs, every community keeps the default roles and the Roles settings say the update is needed. Where part 81 is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.communities') IS NULL THEN RAISE NOTICE 'role permissions: there is no communities table, run part 81 first.'; RETURN; END IF; ALTER TABLE public.communities ADD COLUMN IF NOT EXISTS role_permissions jsonb NOT NULL DEFAULT '{}'::jsonb; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'communities_role_permissions_shape' AND conrelid = 'public.communities'::regclass) THEN ALTER TABLE public.communities ADD CONSTRAINT communities_role_permissions_shape CHECK (jsonb_typeof(role_permissions) = 'object' AND pg_column_size(role_permissions) <= 4096); END IF; REVOKE SELECT (role_permissions), INSERT (role_permissions), UPDATE (role_permissions) ON public.communities FROM PUBLIC, anon, authenticated; GRANT SELECT (role_permissions), UPDATE (role_permissions) ON public.communities TO service_role; END $do$;
notify pgrst, 'reload schema';
